head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.clickBzProcsNo = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

// 수정요청 창에 넘겨주기 위한 변수

// var fr_SecuGrpId = fn_getSecuGrpId(InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 회사선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.fn_GetPar, scwin.fn_SetPar;
// dialog 호출용 함수
// 발행기관목록관련
String.prototype.trim = function() {
    return this.replace(/(^\s*)|(\s*$)/gi, "");
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        if (js_market === "1" || js_market === "2") {
            rdo_SPOT_ISU_TRD_MKT_TP_CD.setValue(js_market);
            panel_mkt_gubun.hide();
        } else {
            panel_mkt_gubun.show("");
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60014.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60014.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Excel_onclick = async function() {
    try {
        if (dts_List.getRowCount() > 0) {
            // 엑셀 로그
            $c.stf.doLogSave("ULDSTF60009.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewOffice(grd_List, "상장예비심사신청현황", "", 8, 0);
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60014.img_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        if (row > 0) {
            // 그리드에서 선택시
            scwin.setBzProcsNo(row);
        }
        if ("COMITE_CASE_FILE_YN" === colid) {
            await scwin.openInvstgCaseDtl();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60014.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60014.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60014.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name txb_COM_NM_onkeydown
 * @description txb_COM_NM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_COM_NM_onkeydown = async function() {
    try {
        if (window.event.keyCode === 13) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60014.txb_COM_NM_onkeydown" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60014.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "&LD_MKT_TP=" + rdo_SPOT_ISU_TRD_MKT_TP_CD.getValue();
    url += "&COM_NM=" + txb_COM_NM.getValue().trim(); // 회사명

    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/ListCaseWrtDtl.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj) {
    scwin.clickBzProcsNo = dts_List.getCellData(Number(obj), "BZ_PROCS_NO");
};

/**
 * @method
 * @name openInvstgCaseDtl
 * @description 위원회안건작성 상세 팝업호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openInvstgCaseDtl = async function() {
    let url = "/lstmgt/ULDSTF60015.gfm";
    await $c.frame.CreateDialogFrame("ULDSTF60015.gfm", url, "상장심사 안건 작성", 50, 50, 680, 450, "window");
};

/**
 * @method
 * @name open
 * @description open 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.open = async function() {
    let url = "/lstmgt/JLDSTF60016.jsp?bzProcsNo=clickBzProcsNo";
    await $c.frame.CreateDialogFrame("JLDSTF60016.jsp", url, "상장심사 안건 작성", 50, 50, 660, 420, "window");

};
